// Results, implications, limitations, conclusions and abstract.  All numbers are read from
// D.tables (generated by scripts/analyze.py and describe_data.py).  Statements of direction
// are conditional on the bootstrap interval; nothing is asserted that the tables do not show.
const { P, H1, H2, table, CAP, image } = require("./lib");
const { cite } = require("./refs");

const f = (x, d = 1) => (x === null || x === undefined || Number.isNaN(+x)) ? "n/a" : Number(x).toFixed(d);
const SUP = { "0": "⁰", "1": "¹", "2": "²", "3": "³", "4": "⁴", "5": "⁵", "6": "⁶", "7": "⁷", "8": "⁸", "9": "⁹", "-": "⁻" };
const fe = (x, d = 2) => {
  if (x === null || x === undefined || Number.isNaN(+x)) return "n/a";
  if (+x === 0) return "0";
  const [m, e] = Number(x).toExponential(d).split("e");
  const ex = String(parseInt(e, 10));
  return ex === "0" ? m : `${m}×10${[...ex].map(ch => SUP[ch]).join("")}`;
};
const pol = { Static: "static", Deterministic: "deterministic", SAA: "SAA", SeasonalSAA: "seasonal SAA", kNN: "kNN contextual", RF: "RF contextual", Robust90: "robust", WaitAndSee: "wait-and-see" };
function T(D, n) { return D.tables[n] || []; }
function ci(r) { return `${f(r.mean_diff ?? r.vci ?? r.mean_diff_obj_vs_SeasonalSAA)} (95 % CI ${f(r.ci_lo ?? r.vci_lo)} to ${f(r.ci_hi ?? r.vci_hi)})`; }
function sign(r) { const lo = r.ci_lo ?? r.vci_lo, hi = r.ci_hi ?? r.vci_hi; return lo > 0 ? 1 : (hi < 0 ? -1 : 0); }
function word(s, pos = "higher", neg = "lower") { return s > 0 ? pos : (s < 0 ? neg : "not distinguishable from"); }

module.exports = (D) => {
const out = { results: [], implications: [], limitations: [], conclusions: [] };
const R = {};
for (const reg of ["R1", "R2"]) {
  R[reg] = { by: T(D, `main_${reg}_by_policy`), pr: T(D, `main_${reg}_paired`), ws: T(D, `main_${reg}_windy_split`) };
}
const get = (reg, p, ref, m) => R[reg].pr.find(r => r.policy === p && r.reference === ref && r.metric === m) || {};
const by = (reg, p) => R[reg].by.find(r => r.policy === p) || {};
const comp = (D.analysis || {}).computation || {};
const nav = T(D, "nav_regime_map"), soc = T(D, "societal_frontier"), dyn = T(D, "dynamic_configuration"),
      sens = T(D, "sensitivity"), rob = T(D, "robustness"), cs = T(D, "computation_scaling");
const nTest = D.n_test_days;

// ---------------- 7.1 main comparison
const rows = [];
for (const reg of ["R1", "R2"]) for (const p of ["Static", "Deterministic", "SAA", "SeasonalSAA", "kNN", "RF", "Robust90", "WaitAndSee"]) {
  const b = by(reg, p); if (!b.policy) continue;
  rows.push([reg, pol[p], f(b.obj), f(b.flown), f(b.cancelled), f(b.switches, 2), f(b.obj_pct_of_waitandsee), f(b.max_ground, 3), f(b.max_air, 3), fe(b.F_day)]);
}
const rf1 = get("R1", "RF", "SeasonalSAA", "obj"), rf2 = get("R2", "RF", "SeasonalSAA", "obj");
const kn1 = get("R1", "kNN", "SeasonalSAA", "obj"), kn2 = get("R2", "kNN", "SeasonalSAA", "obj");
const de1 = get("R1", "Deterministic", "SeasonalSAA", "obj"), de2 = get("R2", "Deterministic", "SeasonalSAA", "obj");
const vss1 = get("R1", "RF", "Deterministic", "obj"), vss2 = get("R2", "RF", "Deterministic", "obj");
const ev1 = get("R1", "WaitAndSee", "RF", "obj"), ev2 = get("R2", "WaitAndSee", "RF", "obj");
const st1 = get("R1", "Static", "SeasonalSAA", "obj"), st2 = get("R2", "Static", "SeasonalSAA", "obj");
const ca1 = get("R1", "RF", "SeasonalSAA", "cancelled"), ca2 = get("R2", "RF", "SeasonalSAA", "cancelled");

out.results.push(
H1("7 Results"),
P(`All results below come from the executed experiments; the corresponding raw files and tables are listed in the Reproducibility Guide. Unless stated otherwise, averages are over the ${nTest} test days and objective values are in flight-equivalents per day for the four corridors together.`),
H2("7.1 Policy comparison"),
P(`Table 7 summarises the out-of-sample performance of the eight policies in both regimes. ${(comp.max_ground_ratio_all_realised_eval <= 1 + 1e-6 && comp.max_air_ratio_all_realised_eval <= 1 + 1e-6) ? "No policy-day evaluated on realised information, in any experiment, exceeded a per-aircraft target (tolerance 10⁻⁶)" : "Some policy-days evaluated on realised information exceeded a per-aircraft target (see the robustness tables)"}: over all such evaluations, including the sensitivity runs, the largest recomputed per-lane ground ratio was ${f(comp.max_ground_ratio_all_realised_eval, 3)} and the largest collision ratio was ${f(comp.max_air_ratio_all_realised_eval, 3)} (a ratio of 1 means the target is met with equality; Table 7 shows the maxima within the main comparison). Both ratios are recomputed from the admitted flows, independently of the optimisation model, on lanes that carry traffic; runs that admit flights with forecast information or assess risk under a different navigation model are reported separately with the robustness results.`),
table(["Regime", "Policy", "Objective", "Flights flown", "Cancelled", "Switches", "% of wait-and-see", "Max ground ratio", "Max collision ratio", "Exp. fatalities/day"], rows,
  [700, 1300, 900, 900, 900, 800, 1000, 950, 950, 1000], { size: 14 }),
CAP("Table 7 Out-of-sample results by policy (means over test days; maxima over all evaluated lanes and hours)"),
P(`**Value of contextual information (RQ1).** Relative to seasonal SAA, the RF contextual policy changed the daily objective by ${ci(rf1)} in regime R1 and by ${ci(rf2)} in regime R2; the kNN policy by ${ci(kn1)} and ${ci(kn2)}. The RF policy was therefore ${word(sign(rf1), "better than", "worse than")} seasonal SAA in R1 and ${word(sign(rf2), "better than", "worse than")} seasonal SAA in R2. Cancellations of pre-approved flights changed by ${ci(ca1)} (R1) and ${ci(ca2)} (R2) per day. Using the forecast as if it were certain (deterministic policy) changed the objective by ${ci(de1)} (R1) and ${ci(de2)} (R2) relative to seasonal SAA; the value of the stochastic solution, RF minus deterministic, was ${ci(vss1)} and ${ci(vss2)}. The gap to perfect information (wait-and-see minus RF) was ${ci(ev1)} and ${ci(ev2)}. The static plan differed from seasonal SAA by ${ci(st1)} and ${ci(st2)}.`),
image(D.fig("Fig06_benchmark_paired"), 2160, 900, 6.4),
CAP("Fig. 6 Paired differences in the daily objective relative to seasonal SAA (means and 95 % bootstrap intervals over test days)"),
);
const wsRows = [];
for (const reg of ["R1", "R2"]) for (const r of R[reg].ws.filter(r => ["RF", "Deterministic", "Static"].includes(r.policy)))
  wsRows.push([reg, r.windy_day ? "windy" : "calm", pol[r.policy], r.n_days, `${f(r.mean_diff_obj_vs_SeasonalSAA)} [${f(r.ci_lo)}, ${f(r.ci_hi)}]`]);
out.results.push(
P(`**Where the value arises.** Splitting test days into those with at least one operating hour above the 12 m/s limit (${D.windy_days_test} of ${nTest} days) and the remaining calm days shows where the contextual advantage is concentrated (Table 8, Fig. 7).`),
table(["Regime", "Days", "Policy", "n", "Objective difference vs seasonal SAA [95 % CI]"], wsRows, [900, 900, 1500, 700, 5360], { size: 16 }),
CAP("Table 8 Paired objective differences on windy and calm test days (intervals treat days as independent)"),
image(D.fig("Fig07_windy_split"), 2100, 780, 6.2),
CAP("Fig. 7 Objective differences relative to seasonal SAA on calm and windy test days"),
);

// ---------------- 7.2 regime map
const navTxt = nav.map(r => `${r.nav_model}, m = ${r.mitigation}: ${f(r.flown_WaitAndSee, 0)}`).join("; ");
out.results.push(
H2("7.2 Which constraint determines capacity (RQ2)"),
P(`The secondary experiments in Sects. 7.2, 7.3 and 7.5 use every second test day (152 days), so their base-case values differ slightly from Table 7. Figure 5 shows the largest uniform flow per lane allowed by the collision constraint for each configuration and navigation model at 5 m/s wind. Figure 8 shows the resulting flights per day under perfect information for each combination of navigation model and mitigation credit. The values were: ${navTxt}. Without mitigation credit, only the light-tailed model E1 leaves the collision constraint slack. Under E2–E4 the corridors carry almost no traffic unless a large share of tail-driven conflicts is credited to tactical mitigation.`),
image(D.fig("Fig05_navigation_models"), 2100, 810, 6.2),
CAP("Fig. 5 Largest uniform flow per lane allowed by the collision constraint (θ_A = 10⁻⁵ per flight hour, wind 5 m/s), by configuration and navigation-error model, without and with 99 % mitigation credit; dashed line: peak demand per corridor"),
image(D.fig("Fig08_regime_map"), 1380, 840, 4.4),
CAP("Fig. 8 Flights flown per day (wait-and-see) by navigation-error model and credited mitigation (152 test days)"),
);

// ---------------- 7.3 dynamic configuration
const dynRows = dyn.filter(r => r.policy === "RF").map(r => [r.setting, f(r.obj), f(r.flown), f(r.switches, 2), f(r.cancelled)]);
out.results.push(
H2("7.3 Switching and configuration menu (RQ3)"),
P(`Table 9 and Fig. 9 report the RF policy under different switching limits, switching costs and configuration menus. ${(() => {
  const rf = dyn.filter(r => r.policy === "RF"), ws = dyn.filter(r => r.policy === "WaitAndSee");
  const maxSw = Math.max(...rf.map(r => r.switches)), maxSwWS = Math.max(...ws.map(r => r.switches));
  const g = st => (rf.find(r => r.setting === st) || {});
  return `The RF plan ${maxSw < 0.005 ? "never switched configuration within a day" : `switched on average at most ${f(maxSw, 2)} times per day`}, whatever the limit and cost (wait-and-see plans switched on average at most ${f(maxSwWS, 2)} times per day). Switching flexibility therefore had no measurable value for the RF plans in this case study. The menu mattered: in R2, removing the dense configurations reduced the objective from ${f(g("R2|M=2|sigma=5.0").obj)} to ${f(g("R2|menu=no-dense").obj)}, and allowing only single lanes reduced it to ${f(g("R2|menu=single-only").obj)}; in R1 removing single-lane configurations cost ${f(g("R1|M=2|sigma=5.0").obj - g("R1|menu=no-single").obj)} per day in fixed costs.`;
})()}`),
table(["Setting", "Objective", "Flown", "Switches", "Cancelled"], dynRows, [3600, 1400, 1400, 1400, 1560], { size: 15 }),
CAP("Table 9 Effect of switching limits, switching cost and menu (RF policy; mean over 152 test days)"),
image(D.fig("Fig10_dynamic_configuration"), 2100, 780, 6.2),
CAP("Fig. 9 Mean objective of the RF policy against the maximum number of switches per corridor-day, for three switching costs"),
);

// ---------------- 7.4 societal frontier
const socRows = soc.map(r => [r.setting, pol[r.policy], r.days, f(r.flown), fe(r.F_day), fe(r.F_day_max),
  (r.cert_gap_max === null || r.cert_gap_max === undefined || Number.isNaN(+r.cert_gap_max)) ? "–" : f(100 * r.cert_gap_max, 2)]);
const socGapMax = (D.analysis || {}).soc_cert_gap_max, socGapMed = (D.analysis || {}).soc_cert_gap_median;
out.results.push(
H2("7.4 Societal-risk frontier (RQ4)"),
P(`The societal ε-constraint limits expected third-party fatalities per hour in the whole study area. On each day the hourly limit is a fraction of the expected societal risk, in that hour, of the unconstrained RF plan under its own forecast scenarios (decision-time information; Sect. 6.3); the coupled problem uses 10 scenarios. Table 10 and Fig. 10 trace flights flown against exact expected fatalities per day. They are computed on a subset of test days because the coupled problem is solved as a MILP (Sect. 4.6). ${(socGapMax ?? 1) <= 1e-3 ? `Every first stage was solved within the 60 s limit to a certified gap of at most ${f(100 * socGapMax, 3)} %, measured against the time-sharing bound and the solver bound. ` : `With a 60 s limit not every first stage is proved optimal: the certified gap, measured against the time-sharing bound and the solver bound, is at most ${f(100 * socGapMax, 2)} % (median ${f(100 * socGapMed, 2)} %); the planned objective may fall short of the optimum by up to that fraction, and flights flown and fatalities at the optimum could differ by other amounts. `}${Math.max((D.analysis || {}).soc_fs_residual_max, (D.analysis || {}).soc_eval_residual_max) <= 1e-6 ? "Every solution passed the independent constraint check" : "Not every solution passed the independent constraint check"} (largest violation ${fe((D.analysis || {}).soc_fs_residual_max)} in planning and ${fe((D.analysis || {}).soc_eval_residual_max)} in evaluation).`),
table(["ε (fraction)", "Policy", "Days", "Flown", "Exp. fatalities/day (mean)", "(max)", "Cert. gap max (%)"], socRows, [1250, 1450, 750, 1150, 1900, 1500, 1360], { size: 15 }),
CAP("Table 10 Societal-risk frontier (regime R2). Certified gap: (upper bound − objective)/|upper bound| of the first-stage problem; – for the unconstrained rows, which are solved exactly"),
image(D.fig("Fig09_societal_frontier"), 1380, 900, 4.4),
CAP("Fig. 10 Flights flown against exact expected third-party fatalities per day as the societal budget is tightened"),
);

// ---------------- 7.5 sensitivity
const sRows = sens.map(r => [r.setting, f(r.flown_RF), f(r.flown_WaitAndSee), `${f(r.vci)} [${f(r.vci_lo)}, ${f(r.vci_hi)}]`, `${f(r.evpi)} [${f(r.evpi_lo)}, ${f(r.evpi_hi)}]`, f(r.max_ground, 3), f(r.max_air, 3)]);
out.results.push(
H2("7.5 Sensitivity analysis"),
P(`Each parameter was varied one at a time around regime R2 (Table 11, Fig. 11). The value of context (RF minus seasonal SAA) and the gap to perfect information are reported with 95 % bootstrap intervals.`),
table(["Setting", "Flown (RF)", "Flown (WS)", "Value of context [CI]", "EVPI [CI]", "Max ground", "Max collision"], sRows, [2000, 1000, 1000, 1800, 1800, 900, 900], { size: 14 }),
CAP("Table 11 One-at-a-time sensitivity around regime R2 (means over 152 test days)"),
image(D.fig("Fig11_sensitivity"), 2160, 1380, 6.4),
CAP("Fig. 11 Sensitivity of the value of contextual information and of flights flown"),
);

// ---------------- 7.6 robustness and computation
const rRows = rob.map(r => [r.setting, pol[r.policy] || r.policy, r.days, f(r.flown), r.days_with_exceed_g, r.exceed_h_ground, r.days_with_exceed_a, r.exceed_h_air, r.max_ground === null ? "∞" : f(r.max_ground, 2), r.max_air === null ? "∞" : f(r.max_air, 2)]);
const csRows = cs.map(r => [({ fast: "structured algorithm", milp: "block-form MILP", extensive: "extensive form (big-M)" })[r.method] || r.method, r.n_scen, r.days, r.vars ? Math.round(r.vars) : "–", f(r.runtime, 2), f(r.runtime_max, 2), (r.gap === null || r.gap === undefined || Number.isNaN(+r.gap)) ? "–" : f(100 * r.gap, 1)]);
out.results.push(
H2("7.6 Robustness and computational performance"),
P(`Table 12 reports three robustness tests in regime R2. In the first, hourly admission uses short-range or day-ahead forecasts instead of the realised wind, and risk is measured on the realised wind. In the second, planning uses navigation model E2 while risk is measured under E3 or E4. In the third, the number of first-stage scenarios is varied. An exceedance hour is an operating hour in which the realised per-lane ratio exceeds 1 on at least one lane, including flights admitted into hours whose realised wind exceeded the platform limit.`),
table(["Test", "Policy", "Days", "Flown", "Days with ground exc.", "Ground exc. hours", "Days with coll. exc.", "Coll. exc. hours", "Max ground", "Max collision"], rRows,
  [1700, 1100, 600, 800, 900, 900, 900, 900, 800, 900], { size: 13 }),
CAP("Table 12 Robustness tests (regime R2)"),
...(() => {
  const sd = T(D, "strict_dayahead");
  if (!sd.length) return [P(`The strict day-ahead variant (context predicted 48 h before the valid time) was not run.`)];
  const word = r => (r.ci_lo > 0 ? "higher than" : r.ci_hi < 0 ? "lower than" : "not distinguishable from");
  const rf = reg => sd.find(r => r.regime === reg && r.policy === "RF");
  const txt = ["R1", "R2"].filter(rf).map(reg => `in ${reg} the mean daily objective of the RF policy was ${word(rf(reg))} that of seasonal SAA (difference ${f(rf(reg).mean_diff_obj_vs_SeasonalSAA, 2)}, 95 % CI ${f(rf(reg).ci_lo, 2)} to ${f(rf(reg).ci_hi, 2)}, ${rf(reg).n_days} days)`).join("; ");
  return [
    P(`Strict day-ahead information. When the context is the forecast predicted 48 h before each valid hour, which is available by the evening before the operating day, ${txt}. Table 13 lists all contextual policies.`),
    table(["Regime", "Policy", "Difference vs seasonal SAA", "95 % CI", "Days"],
      sd.map(r => [r.regime, pol[r.policy] || r.policy, f(r.mean_diff_obj_vs_SeasonalSAA, 2), `${f(r.ci_lo, 2)} to ${f(r.ci_hi, 2)}`, r.n_days]),
      [1300, 2200, 2400, 2400, 1060], { size: 15 }),
    CAP("Table 13 Value of context with the 48-h forecast (daily objective, flight-equivalents)"),
  ];
})(),
P(`Computation. The structured algorithm solved ${comp.first_stage_solves ?? "all"} first-stage problems (the static plan counted once per run) with a mean of ${f(comp.runtime_mean_s, 3)} s and a median of ${f(comp.runtime_median_s, 3)} s. The longest solves, up to ${f(comp.runtime_max_nonstatic_s, 0)} s, were the first ones after a change of parameters, when the capacity LPs are computed and cached; the 60-scenario static plan took at most ${f(comp.runtime_max_static_s, 0)} s. The big-M extensive form with lane indicators does not solve at study scale: on ${comp.extensive_runs ?? 0} SAA problems with 10 scenarios, ${comp.extensive_optimal ?? 0} were proved optimal within the time limit of ${(D.run_log || {}).extensive_time_limit_s ?? 300} s, the remaining MIP gaps were between ${f(100 * comp.extensive_gap_min, 1)} % and ${f(100 * comp.extensive_gap_max, 1)} %, and the best solutions found fell ${f(100 * comp.extensive_shortfall_min, 1)}–${f(100 * comp.extensive_shortfall_max, 1)} % below the optimum of the structured algorithm. The structured algorithm is therefore checked against a block-form MILP of the same model, in which each block is represented by its capacity (Sect. 4.6); this checks steps 1, 3 and 4 of Proposition 4 at study scale, while step 2 is checked against the extensive form on synthetic instances. On ${comp.milp_checks_main ?? 0} policy-days of the main experiments the largest absolute objective difference was ${fe(comp.milp_checks_max_absdiff, 1)} (relative MIP gap 10⁻⁴), and those MILPs took ${f(comp.milp_checks_runtime_mean_s, 1)} s on average. Table 14 and Fig. 12 compare the methods on the same days and scenario sets (largest objective difference between the structured algorithm and the block-form MILP ${fe(comp.fast_vs_milp_max_absdiff, 1)} over ${comp.fast_vs_milp_pairs ?? 0} pairs). The largest constraint residual of any evaluation was ${fe(comp.eval_residual_max, 1)}.`),
table(["Method", "Scenarios", "Days", "Variables", "Mean time (s)", "Max time (s)", "Max MIP gap (%)"], csRows, [2200, 1100, 800, 1300, 1300, 1300, 1360], { size: 15 }),
CAP("Table 14 Computational comparison (regime R2, SAA scenario sets)"),
image(D.fig("Fig12_computation"), 1320, 840, 4.2),
CAP("Fig. 12 Solve time of the structured algorithm, the block-form MILP and the big-M extensive form (the last stopped at its time limit)"),
);

// ---------------- 8 implications (every number read from the result tables)
const ws2 = get("R2", "WaitAndSee", "SeasonalSAA", "obj"), ws1 = get("R1", "WaitAndSee", "SeasonalSAA", "obj");
const bS = by("R2", "SeasonalSAA"), bR = by("R2", "RF"), bD = by("R2", "Deterministic"), bR1 = by("R1", "RF");
const pct = (a, b) => 100 * a / b;
const navOf = (m, mit) => nav.find(r => r.nav_model === m && Math.abs(r.mitigation - mit) < 1e-9) || {};
const robOf = (st, p) => rob.find(r => r.setting === st && r.policy === p) || {};
const socOf = (st, p) => soc.find(r => String(r.setting) === st && r.policy === p) || {};
const sensBase = sens.find(r => r.setting === "base") || {};
const sensSorted = sens.filter(r => r.setting !== "base").map(r => ({ ...r, d: Math.abs(r.flown_RF - sensBase.flown_RF) })).sort((a, b) => b.d - a.d);
const topSens = sensSorted.slice(0, 3).map(r => `${r.setting} (${f(r.flown_RF, 0)} flights/day against ${f(sensBase.flown_RF, 0)} in the base case)`).join(", ");
const nowSR = robOf("nowcast-shortrange", "RF"), nowDA = robOf("nowcast-dayahead", "RF");
const mis3 = robOf("misspec-E3-degraded", "RF"), mis4 = robOf("misspec-E4-KimBae", "RF");
const socN = socOf("none", "RF"), soc10 = socOf("0.1", "RF"), soc50 = socOf("0.5", "RF");
const share2 = pct(rf2.mean_diff, ws2.mean_diff);
const rfSt2 = get("R2", "RF", "Static", "obj");
const wsSplit = R["R2"].ws.filter(r => r.policy === "RF");
const wsCalm = { ...(wsSplit.find(r => !r.windy_day) || {}) }, wsWindy = { ...(wsSplit.find(r => r.windy_day) || {}) };
wsCalm.mean_diff = wsCalm.mean_diff_obj_vs_SeasonalSAA; wsWindy.mean_diff = wsWindy.mean_diff_obj_vs_SeasonalSAA;
const navVci = (m, mit) => { const r = navOf(m, mit); return { mean_diff: r.vci_obj, ci_lo: r.vci_lo, ci_hi: r.vci_hi }; };
out.implications.push(
H1("8 Operational implications"),
P(`**Capacity is set by navigation performance, not by ground risk.** In both regimes the largest per-lane ground-risk ratio stayed far below its target (at most ${f(bR.max_ground, 2)} of θ_G in R2), while in R2 the collision constraint was met with equality. Across error models, flights flown under perfect information ranged from ${f(navOf("E1-precise", 0).flown_WaitAndSee, 0)} per day (E1, demand-limited) through ${f(navOf("E2-measured", 0).flown_WaitAndSee, 0)} (E2 without mitigation credit) to ${f(navOf("E4-KimBae", 0).flown_WaitAndSee, 0)} (E4 without credit); a credit of 99 % for tactical mitigation restored ${f(navOf("E2-measured", 0.99).flown_WaitAndSee, 0)}, ${f(navOf("E3-degraded", 0.99).flown_WaitAndSee, 0)} and ${f(navOf("E4-KimBae", 0.99).flown_WaitAndSee, 0)} flights per day under E2, E3 and E4. For a corridor operator, the decisive inputs are therefore a validated navigation-error tail and an evidenced mitigation credit. Ground risk becomes binding only under stricter or more exposed settings: with θ_G = 10⁻⁷ the RF policy flew ${f((sens.find(r => r.setting === "theta_G=1e-07") || {}).flown_RF, 0)} flights per day, and with a pedestrian density of 0.1 m⁻² the largest ground ratio reached ${f((sens.find(r => r.setting === "ped_density=0.1") || {}).max_ground, 2)}. The sensitivity analysis points the same way: the parameters that moved flights flown most were ${topSens}.`),
P(`**Day-ahead context has small and model-dependent value.** In R1, where capacity exceeds demand, all stochastic policies coincided and contextual information had no value. In R2 the contextual policies improved on seasonal SAA by ${f(rf2.mean_diff)} (RF) and ${f(kn2.mean_diff)} (kNN) flight-equivalents per day, about ${f(pct(rf2.mean_diff, bS.obj), 1)} % of the daily objective; RF recovered ${f(share2, 0)} % of the gap between seasonal SAA and perfect information (${f(ws2.mean_diff)}). A plan that uses no information at all, the static plan, also beat seasonal SAA (${ci(st2)}), and RF improved on it by only ${ci(rfSt2)}. The gain arose on calm days (${ci(wsCalm)}), where wind changes collision capacity without exceeding the platform limit; on the ${D.windy_days_test} days with wind above the limit the difference was ${sign(wsWindy) === 0 ? "not distinguishable from zero" : (sign(wsWindy) > 0 ? "positive" : "negative")} (${ci(wsWindy)}). Across the regime map the sign was not stable: with 90 % credit, the difference was ${sign(navVci("E3-degraded", 0.9)) === 0 ? "not distinguishable from zero" : (sign(navVci("E3-degraded", 0.9)) > 0 ? "positive" : "negative")} under E3 (${ci(navVci("E3-degraded", 0.9))}) and ${sign(navVci("E4-KimBae", 0.9)) === 0 ? "not distinguishable from zero" : (sign(navVci("E4-KimBae", 0.9)) > 0 ? "positive" : "negative")} under E4 (${ci(navVci("E4-KimBae", 0.9))}). The value of context grew where wind matters more: to ${f((sens.find(r => r.setting === "gamma=0.2") || {}).vci)} per day when navigation errors grow faster with wind (γ = 0.2) and to ${f((sens.find(r => r.setting === "lambda_f=0.0001") || {}).vci)} with a ten-fold loss-of-control rate (Table 11). The deterministic policy, which plans on the single forecast trajectory and mean demand, was much worse (${f(de2.mean_diff)} per day, ${f(pct(de2.mean_diff, bS.obj), 1)} %); its loss combines the neglect of uncertainty with the forecast's low bias (${f(D.summary.skill_test.bias_ms, 2)} m/s), and these were not separated here.`),
P(`**Hourly admission must use current information with a margin.** When flights were admitted on forecasts and risk was measured on the realised wind, collision targets were exceeded on ${nowSR.days_with_exceed_a} of ${nowSR.days} days with short-range forecasts and on ${nowDA.days_with_exceed_a} of ${nowDA.days} days with day-ahead forecasts, and the ground target was exceeded, or flights were admitted in hours whose realised wind exceeded the platform limit, on ${nowSR.days_with_exceed_g} and ${nowDA.days_with_exceed_g} days. The plan can be made with forecasts; admission cannot, unless it carries an explicit margin or is checked against current wind.`),
P(`**An optimistic error model is not a conservative approximation.** Planning with E2 and 90 % credit when errors actually follow E3 or E4 breached the collision target in ${mis3.exceed_h_air} (E3) and ${mis4.exceed_h_air} (E4) of the ${mis3.days * D.cfg.hours.length} evaluated operating hours, on every one of the ${mis3.days} days (largest ratios ${f(mis3.max_air, 1)} and ${f(mis4.max_air, 1)}); under E4 the ground target was also breached in ${mis4.exceed_h_ground} hours. A navigation-performance requirement for corridor use should therefore be stated as a bound on the error tail, verified by measurement, rather than as an RMS value.`),
P(`**Societal risk can be traded against throughput explicitly.** Limiting expected third-party fatalities per hour to half of the unconstrained plan's expected value reduced flights flown on the frontier days from ${f(socN.flown, 0)} to ${f(soc50.flown, 0)} per day; a limit of 10 % reduced them to ${f(soc10.flown, 0)}. Because the per-flight targets do not bound aggregate risk, a regulator who wants a cap on total risk in an area has to impose it separately, and the frontier shows its price in flights.`),
);
out.limitations.push(
H1("9 Limitations"),
P(`The study has several limitations, and the conclusions should be read with them in mind.`),
P(`**Navigation-error tails.** The most consequential parameter of the collision model is not identified by published data. Measured total-system errors constrain the core of the distribution but not its tail ${cite("geister")}. The paper therefore reports all results conditionally on four error models and on an assumed tactical-mitigation credit. Capacity figures obtained under any single model should not be read as validated capacities.`),
P(`**Exposure.** pNEUMA observes road vehicles on ${D.summary.pneuma_dates.length} weekday mornings in 2018 over about 1.3 km² ${cite("pneuma2020")}; the model's layer is fitted on two of these mornings. Road exposure in other hours, on weekends and in later years is extrapolated, and pedestrians are not observed at all. The held-out checks confirm the spatial pattern for open and in-vehicle exposure on unseen days and in a later slot, but heavy-vehicle exposure is poorly predicted (Sect. 5.1). The corridor rule uses the bounding boxes of the drone fields of view; parts of these boxes contain streets that pNEUMA did not film (Fig. 2), where road-vehicle exposure is set to zero and only the assumed pedestrian density applies. Road exposure under some corridor segments, and hence ground and societal risk, is therefore underestimated; ground risk was not binding in the main regimes, but the societal frontier is affected.`),
P(`**Demand.** Drone-delivery demand is synthetic. The value of contextual information measured here arises from weather and its effect on the safety-feasible region, not from demand prediction.`),
P(`**Risk model.** The harm model, lethal area and sheltering classes are literature values and assumptions; occupants of buildings are assumed fully protected; collision-induced crashes are assumed to have the same ground consequence as loss-of-control crashes; and collisions between corridors are not modelled. The proof that the problem separates by corridor relies on this. Where two corridors cross in configurations with stacked layers, the upper north–south layer and the lower east–west layer are only 20 m apart vertically, the same spacing as stacked lanes within a corridor, so the omitted crossing term is not negligible in principle and would have to be added for an operational assessment. Reich's model assumes long parallel tracks with stationary errors, which also makes the in-trail rate decrease when lateral errors grow (Supplementary S3).`),
P(`**Weather.** Realised wind is taken from a reanalysis rather than from observations at flight level, and the platform limit of 12 m/s is applied to hourly mean wind at 100 m; gusts are not modelled.`),
P(`**Scope of the decision model.** The recourse assumes that unserved requests are lost, which keeps the two-stage form exact; deferral would require a multistage model. A single operator is assumed. Safety targets are research criteria, not regulatory requirements.`),
);
out.conclusions.push(
H1("10 Conclusions"),
P(`We formulated day-ahead corridor configuration and flight admission for urban drone delivery as a two-stage stochastic programme whose feasible region is defined exactly, per aircraft flight hour, by ground-harm and collision constraints that depend on wind. With risk normalised per flight hour the problem is an exact mixed-integer linear programme; it separates by corridor and reduces to cached capacity linear programmes, a concave one-dimensional problem per hour and a dynamic programme, which solved the ${comp.first_stage_solves} first-stage problems of the study in ${f(comp.runtime_mean_s, 2)} s on average (median ${f(comp.runtime_median_s, 3)} s), whereas the extensive form did not solve within ${(D.run_log || {}).extensive_time_limit_s ?? 300} s. The societal ε-frontier is solved through an equivalent block formulation; ${((D.analysis || {}).soc_cert_gap_max ?? 1) <= 1e-3 ? `every frontier problem was solved with a certified gap of at most ${f(100 * (D.analysis || {}).soc_cert_gap_max, 3)} %` : `the largest certified gap of a frontier problem was ${f(100 * (D.analysis || {}).soc_cert_gap_max, 1)} %`}.`),
P(`Applied to central Athens with official pNEUMA exposure data and archived ECMWF forecasts, the out-of-sample evaluation on ${nTest} test days of 2026 gave three main findings. First, capacity is governed by the navigation-error tail and the credited mitigation, not by ground risk; under error models E2–E4 and without mitigation credit, the corridors carry a small fraction of demand. Second, contextual scenario weighting improved on a calendar-based benchmark in regime R2 by about ${f(pct(rf2.mean_diff, bS.obj), 1)} % of the daily objective, had no value in R1, and was not consistently beneficial across the other error models; planning on the single forecast trajectory with mean demand was clearly harmful. Third, admitting flights on forecasts breaches the per-flight targets on many days, and planning with an optimistic error model breaches them in almost every operating hour. These are negative or modest findings for the value of day-ahead prediction, and they are reported as such.`),
P(`The conclusions are conditional on the assumed risk targets, the four navigation-error models, synthetic demand and exposure observed on four weekday mornings. The most valuable next steps are measurements of drone navigation-error tails in urban corridors, observations of pedestrian exposure, and a multistage extension in which unserved requests can be deferred.`),
);
const abs = () => `Urban drone-delivery corridors must be configured before the weather is known, and flights admitted only if risk to people on the ground and to other aircraft stays within targets. We formulate day-ahead corridor configuration and hourly flight admission as a two-stage stochastic programme in which ground-harm and collision risk per aircraft flight hour define an exact, wind-dependent feasible region, and scenarios are weighted by the day-ahead wind forecast. The exact mixed-integer linear programme separates by corridor and reduces to cached capacity linear programmes, a concave one-dimensional problem per hour and a dynamic programme, giving an exact algorithm where the extensive form does not solve; aggregate societal risk enters through an ε-constraint. The case study uses official pNEUMA trajectory data for road exposure in central Athens, OpenStreetMap buildings, ERA5 wind and archived ECMWF forecasts, with out-of-sample evaluation on ${nTest} days of 2026. Capacity is governed by the navigation-error tail and the credited tactical mitigation rather than by ground risk. In the regime where capacity binds, contextual weighting improved on a calendar-based benchmark by ${f(rf2.mean_diff)} flight-equivalents per day (95 % CI ${f(rf2.ci_lo)} to ${f(rf2.ci_hi)}; about ${f(pct(rf2.mean_diff, bS.obj), 1)} % of the objective), but not consistently across error models; planning on the single forecast trajectory lost ${f(-pct(de2.mean_diff, bS.obj), 1)} %. Admitting flights on forecasts, or planning with an optimistic error model, breached the per-flight targets. Because tail parameters of drone navigation errors are not identified by published data, all results are reported conditionally on four error models.`;
out.abstract = abs();
out.keywords = ["Drone delivery", "Stochastic programming", "Contextual optimization", "Third-party risk", "Collision risk", "Urban air traffic management"];
return out;
};
